.ds-preview {font-family: Arial, Helvetica, sans-serif; line-height: 1.55; color: var(--ink, #171b26); } .ds-preview a {color: inherit; text-decoration: none; text-underline-offset: 0.3em;} .ds-preview a:hover {text-decoration: underline;} .ds-preview button {font: inherit; cursor: pointer;} .ds-preview button:disabled {cursor: default;} .ds-preview :focus-visible {outline: 3px solid var(--accent, #1847e6); outline-offset: 5px;} .ds-preview p {margin: 0; overflow-wrap: anywhere;} .ds-preview .ds-build-explorer {background: var(--ink, #171b26); color: var(--canvas, #f7f5ef); padding: 1.25rem 1.75rem;} .ds-preview .ds-build-explorer :focus-visible {outline-color: var(--soft-blue, #a6bedf);} .ds-preview .ds-build-explorer ::selection {background: var(--canvas, #f7f5ef); color: var(--accent, #1847e6);} .ds-preview .ds-mobile-system-map {display: none;} .ds-preview .ds-map-guides {color: var(--map-line, #667891);} .ds-preview .ds-map-path {stroke: var(--map-line, #667891); stroke-width: 1.2;} .ds-preview .ds-map-path.ds-is-selected {stroke: var(--map-active, #adc6ff); stroke-width: 2.5;} .ds-preview .ds-map-node {stroke: var(--map-line, #667891); stroke-width: 1.2; color: var(--dark-muted, #b7c0ce);} .ds-preview .ds-map-node.ds-is-selected {stroke: var(--map-active, #adc6ff); color: var(--canvas, #f7f5ef);} .ds-preview .ds-map-node.ds-is-selected > rect:first-child {fill: var(--accent, #1847e6);} .ds-preview .ds-map-node text {fill: currentColor; stroke: none; font-size: 12px; letter-spacing: 1px; font-family: Arial, sans-serif;} .ds-preview .ds-map-hub circle {fill: var(--canvas, #f7f5ef);} .ds-preview .ds-map-hub path {stroke: var(--ink, #171b26); stroke-width: 4;} .ds-preview .ds-sketch-note {font-size: 0.75rem; color: var(--dark-muted, #b7c0ce); margin-top: 0.75rem;} @media (prefers-reduced-motion: no-preference) {.ds-preview .ds-map-path.ds-is-selected {animation: connect-path 700ms var(--motion-ease, cubic-bezier(0.16, 1, 0.3, 1));} .ds-preview .ds-map-node > rect:first-child {transition: fill var(--motion-duration, 240ms);} @keyframes connect-path {
    from {
      stroke-dasharray: 1;
      stroke-dashoffset: 1;
    }
    to {
      stroke-dasharray: 1;
      stroke-dashoffset: 0;
    }
  }} @media (max-width: 43.75rem) {.ds-preview .ds-build-explorer {padding: 1rem;} .ds-preview .ds-mobile-system-map {display: block; width: 100%; height: auto;}} .ds-preview .ds-mobile-system-map { display: block; width: 100%; height: auto; }
